// Card validation and ids, shared by the server and the browser board.
// ESM, no Node-only imports: works in Node and in the browser as-is.

export const COLUMNS = ['todo', 'doing', 'done'];

export const TITLE_MAX = 80;

export function newId() {
  return globalThis.crypto.randomUUID();
}

// Validates and normalizes card input.
// partial=false (create): title required; description/assignee default to ''; column defaults to 'todo'.
// partial=true (update): only the fields present in input are checked and returned, so an
// update never blanks fields it didn't mention.
// Returns { ok: true, value } or { ok: false, errors: [{ field, message }] }.
export function validateCard(input, { partial = false } = {}) {
  const errors = [];
  const value = {};

  if (input === null || typeof input !== 'object' || Array.isArray(input)) {

shared/cards.js 2/3:
    return { ok: false, errors: [{ field: 'card', message: 'card must be an object' }] };
  }
  const has = (key) => Object.hasOwn(input, key) && input[key] !== undefined;

  if (has('id')) {
    if (typeof input.id === 'string' && input.id.trim()) value.id = input.id;
    else errors.push({ field: 'id', message: 'id must be a non-empty string' });
  }

  if (has('title')) {
    if (typeof input.title !== 'string') {
      errors.push({ field: 'title', message: 'title must be a string' });
    } else {
      const title = input.title.trim();
      if (!title) errors.push({ field: 'title', message: 'title is required' });
      else if (title.length > TITLE_MAX) {
        errors.push({ field: 'title', message: `title must be at most ${TITLE_MAX} characters` });
      } else value.title = title;
    }
  } else if (!partial) {

shared/cards.js 3/3:
    errors.push({ field: 'title', message: 'title is required' });
  }

  for (const field of ['description', 'assignee']) {
    if (has(field)) {
      if (typeof input[field] === 'string') value[field] = input[field].trim();
      else errors.push({ field, message: `${field} must be a string` });
    } else if (!partial) {
      value[field] = '';
    }
  }

  if (has('column')) {
    if (COLUMNS.includes(input.column)) value.column = input.column;
    else errors.push({ field: 'column', message: `column must be one of ${COLUMNS.join(', ')}` });
  } else if (!partial) {
    value.column = COLUMNS[0];
  }

  if (has('position')) {
    if (Number.isInteger(input.position) && input.position >= 0) value.position = input.position;
    else errors.push({ field: 'position', message: 'position must be a non-negative integer' });
  }

  return errors.length ? { ok: false, errors } : { ok: true, value };
}

proposal.contractText:
File: shared/cards.js
Owner: Claude (project-3-claude)
Format: ESM (export keyword); usable in both Node.js and browser (no Node-specific built-ins except crypto.randomUUID which is available in both).

Exports:

  export const COLUMNS = ['todo', 'doing', 'done'];
  // Ordered list of valid column identifiers.

  export const TITLE_MAX = 80;

  export function newId(): string
  // Returns crypto.randomUUID(). Alias: createId() is NOT exported; callers use newId().

  export function validateCard(input: object, options?: { partial?: boolean }): { ok: true, value: Card } | { ok: false, errors: Array<{ field: string, message: string }> }
  // When partial=false (default): title is required, trimmed, 1..TITLE_MAX chars.
  // When partial=true: title may be absent (for PATCH updates).
  // description and assignee: default to '' if absent, trimmed.
  // column: must be one of COLUMNS if present; defaults to COLUMNS[0] ('todo') if absent and partial=false.
  // position: if present must be a non-negative integer.
  // On success: returns { ok: true, value: normalized Card object }.
  // On failure: returns { ok: false, errors: [{ field: 'title'|'column'|'position'|..., message: string }, ...] }.
  // The server MUST return validation errors as: 400 { "error": string } where the string may include field detail;
  //   the browser renders server error responses inline without re-parsing field structure from the HTTP body.

Card type (for reference):
  { id: string, title: string, description: string, assignee: string, column: 'todo'|'doing'|'done', position: number }

BASE URL: http://localhost:3000

Columns (exhaustive, ordered): ["todo", "doing", "done"]

Card JSON shape:
  { "id": string (UUID), "title": string, "description": string, "assignee": string, "column": "todo"|"doing"|"done", "position": integer (0-based, contiguous per column) }

Endpoints:

GET /api/cards
  Response 200: Card[] sorted ascending by column-order then position.

GET /api/cards/:id
  Response 200: Card
  Response 404: { "error": string }

POST /api/cards
  Request body: { "title": string (required), "description"?: string, "assignee"?: string, "column"?: "todo"|"doing"|"done" (default "todo") }
  Response 201: Card (appended at end of target column, position = current column length)
  Response 400: { "error": string }

PATCH /api/cards/:id
  For field updates: { "title"?: string, "description"?: string, "assignee"?: string }
  For move (may be combined with field updates): add { "column"?: "todo"|"doing"|"done", "position"?: integer }
  Response 200: Card (with renumbered positions in affected columns)
  Response 400: { "error": string }
  Response 404: { "error": string }

DELETE /api/cards/:id
  Response 204: (no body)
  Response 404: { "error": string }

All error responses: { "error": string }
Content-Type: application/json for all non-204 responses.

File: store/index.js
Owner: Droid (project-3-droid)
Format: ESM (export keyword)

Export:
  export async function createStore(options?: { file?: string }): Promise<Store>
  // If options.file is provided, persists to that JSON file path (atomic fsync+rename writes).
  // If options.file is omitted or undefined, uses in-memory storage (no file I/O); required for test isolation.

Store interface (all methods are async / return Promises):

  listCards(): Promise<Card[]>
  // Returns all cards sorted by column order (todo, doing, done) then by position ascending.

  getCard(id: string): Promise<Card | null>
  // Returns the card with the given id, or null if not found.

  createCard(card: Card): Promise<Card>
  // Persists a card that already has all fields set (id, title, description, assignee, column, position).
  // Appends to end of the specified column; caller supplies position = column.length.
  // Returns the persisted card.

  updateCard(id: string, fields: Partial<{title,description,assignee}>): Promise<Card | null>
  // Applies field patches; returns updated card or null if not found.

  moveCard(id: string, column: 'todo'|'doing'|'done', position: number): Promise<Card | null>
  // Moves card to column at 0-based position index.
  // Renumbers positions in both the source and destination columns so each is contiguous 0..n-1.
  // Clamps position to valid range (0..destLength after removal).
  // Returns updated card or null if not found.

  deleteCard(id: string): Promise<Card | null>
  // Removes card; renumbers remaining cards in its column.
  // Returns the deleted card as it was, or null if not found.

  close(): Promise<void>
  // Flushes any pending writes and releases file handles. No-op for in-memory store.

Change events (internal, used by server/ SSE layer):
  The Store object extends/mixes EventEmitter.
  After each durable save, emits: store.emit('change', { type: 'card.created'|'card.updated'|'card.moved'|'card.deleted', card: Card })
  The card field is the full Card as it exists after the operation (or as it was, for deleted).

Card shape:
  { id: string, title: string, description: string, assignee: string, column: 'todo'|'doing'|'done', position: number }

Error codes thrown (as Error with .code property):
  'NOT_FOUND'        — id does not exist (methods return null rather than throw for missing; reserved for internal use)
  'VALIDATION_ERROR' — invalid input (store may rely on shared/cards.js for validation)

Columns (exhaustive, ordered): ['todo', 'doing', 'done']

